def nested_list_iqr(L):
    data = sorted(float(x) for sub in L for x in sub)
    n = len(data)
    if n == 0:
        return float('nan')

    def percentile(p):
        pos = p * (n - 1)
        lo = int(pos)
        hi = min(lo + 1, n - 1)
        frac = pos - lo
        return data[lo] + (data[hi] - data[lo]) * frac

    return float(percentile(0.75) - percentile(0.25))

