            return cleaned, None
    all_vals = [v for c in cols for v in cleaned[c]]
    mn = min(all_vals)
    mx = max(all_vals)
    if mx == mn:
        return cleaned, None
    n_edges = max(2, min(11, rows // 2))
    step = (mx - mn) / (n_edges - 1)
    edges = [mn + i * step for i in range(n_edges)]
    edges[0] = mn
    edges[-1] = mx
