import math


def _jacobi_eigen(A):
    n = len(A)
    A = [row[:] for row in A]
    V = [[1.0 if i == j else 0.0 for j in range(n)] for i in range(n)]
    if n == 0:
        return [], V
    total = sum(A[i][j] * A[i][j] for i in range(n) for j in range(n))
    if total == 0.0:
        return [A[i][i] for i in range(n)], V
    for _ in range(100):
        off = sum(A[i][j] * A[i][j] for i in range(n) for j in range(n) if i != j)
        if off <= 1e-30 * total:
            break
        for p in range(n - 1):
            for q in range(p + 1, n):
                apq = A[p][q]
                if apq == 0.0:
                    continue
                theta = (A[q][q] - A[p][p]) / (2.0 * apq)
                if theta == 0.0:
                    t = 1.0
                else:
                    sgn = 1.0 if theta > 0 else -1.0
                    t = sgn / (abs(theta) + math.hypot(theta, 1.0))
                c = 1.0 / math.sqrt(t * t + 1.0)
                s = t * c
                for k in range(n):
                    akp = A[k][p]
                    akq = A[k][q]
                    A[k][p] = c * akp - s * akq
                    A[k][q] = s * akp + c * akq
                for k in range(n):
                    apk = A[p][k]
                    aqk = A[q][k]
                    A[p][k] = c * apk - s * aqk
                    A[q][k] = s * apk + c * aqk
                A[p][q] = 0.0
                A[q][p] = 0.0
                for k in range(n):
                    vkp = V[k][p]
                    vkq = V[k][q]
                    V[k][p] = c * vkp - s * vkq
                    V[k][q] = s * vkp + c * vkq
    return [A[i][i] for i in range(n)], V


def pca_transform(rows, n_components):
    rows = [tuple(float(x) for x in r) for r in rows]
    n = len(rows)
    d = len(rows[0]) if n else 0
    for r in rows:
        if len(r) != d:
            raise ValueError("rows must have equal length")
    if not isinstance(n_components, int) or isinstance(n_components, bool):
        raise ValueError("n_components must be an integer")
    if n_components < 0 or n_components > min(n, d):
        raise ValueError("invalid n_components")
    if n == 0:
        return []
    if n_components == 0:
        return [[] for _ in rows]
    means = [sum(r[j] for r in rows) / n for j in range(d)]
    centered = [[r[j] - means[j] for j in range(d)] for r in rows]
    denom = (n - 1) if n > 1 else 1
    cov = [[0.0] * d for _ in range(d)]
    for i in range(d):
        for j in range(i, d):
            s = sum(c[i] * c[j] for c in centered) / denom
            cov[i][j] = s
            cov[j][i] = s
    vals, V = _jacobi_eigen(cov)
    order = sorted(range(d), key=lambda i: -vals[i])
    comps = []
    for idx in order[:n_components]:
        vec = [V[k][idx] for k in range(d)]
        best = 0
        for k in range(d):
            if abs(vec[k]) > abs(vec[best]):
                best = k
        if vec[best] < 0:
            vec = [-x for x in vec]
        comps.append(vec)
    result = []
    for c in centered:
        result.append([float(sum(c[k] * v[k] for k in range(d))) for v in comps])
