import math


def _gamma_p_series(a, x):
    ap = a
    s = 1.0 / a
    d = s
    for _ in range(10000):
        ap += 1.0
        d *= x / ap
        s += d
        if abs(d) < abs(s) * 1e-16:
            break
    return s * math.exp(-x + a * math.log(x) - math.lgamma(a))


def _gamma_q_cf(a, x):
    tiny = 1e-300
    b = x + 1.0 - a
    c = 1.0 / tiny
    d = 1.0 / b
    h = d
    for i in range(1, 10000):
        an = -i * (i - a)
        b += 2.0
        d = an * d + b
        if abs(d) < tiny:
            d = tiny
        c = b + an / c
        if abs(c) < tiny:
            c = tiny
        d = 1.0 / d
        delta = d * c
        h *= delta
        if abs(delta - 1.0) < 1e-16:
            break
    return math.exp(-x + a * math.log(x) - math.lgamma(a)) * h


def _chi2_sf(x, k):
    if x <= 0:
        return 1.0
    a = k / 2.0
    xx = x / 2.0
    if xx < a + 1.0:
        q = 1.0 - _gamma_p_series(a, xx)
    else:
        q = _gamma_q_cf(a, xx)
    return min(1.0, max(0.0, q))


def chi_square_independence_pvalue(data, col1, col2):
    if col1 not in data or col2 not in data:
        raise ValueError("column missing from data")
    x = list(data[col1])
    y = list(data[col2])
    if len(x) != len(y):
        raise ValueError("columns must have equal length")
    if len(x) == 0:
        raise ValueError("empty data")
    rows = []
    for v in x:
        if v not in rows:
            rows.append(v)
    cols = []
    for v in y:
        if v not in cols:
            cols.append(v)
    ri = {v: i for i, v in enumerate(rows)}
    ci = {v: i for i, v in enumerate(cols)}
    table = [[0] * len(cols) for _ in rows]
    for a, b in zip(x, y):
        table[ri[a]][ci[b]] += 1
    for r in table:
        for c in r:
            if c < 5:
                raise ValueError("contingency table cell has fewer than 5 observations")
    n = float(len(x))
    rsum = [sum(r) for r in table]
    csum = [sum(table[i][j] for i in range(len(rows))) for j in range(len(cols))]
    dof = (len(rows) - 1) * (len(cols) - 1)
    if dof == 0:
        return 1.0
    chi2 = 0.0
    for i in range(len(rows)):
        for j in range(len(cols)):
            e = rsum[i] * csum[j] / n
            o = float(table[i][j])
            if dof == 1:
                diff = e - o
                mag = min(0.5, abs(diff))
                if diff > 0:
                    o += mag
                elif diff < 0:
                    o -= mag
            chi2 += (o - e) ** 2 / e
    return float(_chi2_sf(chi2, dof))

