import numpy as np


def pca_transform(rows, n_components):
    rows = list(rows)
    n = len(rows)
    d = len(rows[0]) if n > 0 else 0
    if not isinstance(n_components, (int, np.integer)) or isinstance(n_components, bool):
        raise ValueError("n_components must be an integer")
    if n_components < 0 or n_components > min(n, d):
        raise ValueError("n_components must be between 0 and min(n_rows, n_features)")
    for r in rows:
        if len(r) != d:
            raise ValueError("all rows must have the same length")
    if n_components == 0:
        return [[] for _ in range(n)]
    X = np.asarray(rows, dtype=float)
    Xc = X - X.mean(axis=0)
    _, s, Vt = np.linalg.svd(Xc, full_matrices=False)
    order = np.argsort(-s, kind="stable")
    comps = Vt[order[:n_components]].copy()
    for i in range(comps.shape[0]):
        idx = int(np.argmax(np.abs(comps[i])))
        if comps[i, idx] < 0:
            comps[i] = -comps[i]
    proj = Xc @ comps.T
    return [[float(v) for v in row] for row in proj]
